SCRIPT=f'''<script id="beon-v3-script">(()=>{{const KEY='beon-favorites-v3',getFav=()=>JSON.parse(localStorage.getItem(KEY)||'[]'),setFav=a=>localStorage.setItem(KEY,JSON.stringify(a)),params=new URLSearchParams(location.search);const toast=m=>{{let t=document.getElementById('v3-toast');if(!t){{t=document.createElement('div');t.id='v3-toast';t.style='position:fixed;left:50%;bottom:96px;transform:translateX(-50%);z-index:150;padding:10px 14px;border:1px solid #ffffff18;border-radius:999px;background:#090711f5;color:#fff;font:600 12px Space Grotesk,sans-serif;box-shadow:0 15px 45px #0008';document.body.appendChild(t)}}t.textContent=m;clearTimeout(t._x);t._x=setTimeout(()=>t.remove(),1800)}};const share=(u,title)=>navigator.share?navigator.share({{title,url:u}}).catch(()=>{{}}):navigator.clipboard?.writeText(u).then(()=>toast('Link copiado'));
function admin(){{if(params.get('admin')!=='1')return;const load=()=>{{const sb=window.supabase.createClient('{SUPA_URL}','{SUPA_KEY}');document.body.innerHTML=`<div class="v3-admin on"><div class="wrap"><div class="panel"><div style="display:flex;justify-content:space-between;align-items:center"><div><div style="color:#3fe0d0;font-size:11px;letter-spacing:.15em">BE·ON 3.0</div><h1>Painel administrativo</h1><div class="status" id="admStatus">Login necessário.</div></div><button id="admClose" class="ghost">Fechar</button></div></div><div class="panel" id="loginPanel"><div class="grid2"><input id="admEmail" placeholder="E-mail"><input id="admPass" type="password" placeholder="Senha"></div><div class="actions"><button id="admLogin">Entrar</button></div></div><div class="panel" id="appPanel" style="display:none"><div class="actions"><button id="newEvent">Novo evento</button><button id="logout" class="ghost">Sair</button></div><div class="panel"><div class="grid2"><input id="fName" placeholder="Nome"><input id="fDate" type="date"><input id="fLocation" placeholder="Local"><input id="fArtists" placeholder="Artistas / line-up"><input id="fPurchase" placeholder="Link de compra"><input id="fImage" placeholder="URL da capa"><input id="fSource" placeholder="Pasta do Drive / fonte"><select id="fPublished"><option value="true">Publicado</option><option value="false">Oculto</option></select><select id="fFeatured"><option value="false">Não destacado</option><option value="true">Destacado</option></select></div><textarea id="fDescription" placeholder="Descrição"></textarea><div class="actions"><button id="saveEvent">Salvar</button><button id="cancelEdit" class="ghost">Cancelar</button></div></div><div id="eventTable"></div></div></div></div>`;let editId=null;const $=id=>document.getElementById(id),st=m=>$('admStatus').textContent=m,clear=()=>{{editId=null;['fName','fDate','fLocation','fArtists','fPurchase','fImage','fSource','fDescription'].forEach(i=>$(i).value='')}};const fill=e=>{{editId=e.id;$('fName').value=e.name||'';$('fDate').value=e.event_date||'';$('fLocation').value=e.location||'';$('fArtists').value=e.artists||'';$('fPurchase').value=e.purchase_url||'';$('fImage').value=e.image_url||'';$('fSource').value=e.source_url||'';$('fDescription').value=e.description||'';$('fPublished').value=String(e.published);$('fFeatured').value=String(e.featured)}};async function load(){{const r=await sb.from('events').select('*').order('event_date');if(r.error)return st(r.error.message);$('eventTable').innerHTML=`<table><thead><tr><th>Evento</th><th>Data</th><th>Publicado</th><th>Ações</th></tr></thead><tbody>${{r.data.map(e=>`<tr><td>${{e.name}}</td><td>${{e.event_date||''}}</td><td>${{e.published?'Sim':'Não'}}</td><td><button data-edit="${{e.id}}" class="ghost">Editar</button> <button data-del="${{e.id}}" class="danger">Excluir</button></td></tr>`).join('')}}</tbody></table>`;document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>fill(r.data.find(x=>x.id===b.dataset.edit)));document.querySelectorAll('[data-del]').forEach(b=>b.onclick=async()=>{{if(!confirm('Excluir este evento?'))return;const x=await sb.from('events').delete().eq('id',b.dataset.del);st(x.error?.message||'Evento excluído');load()}})}};$('admLogin').onclick=async()=>{{const r=await sb.auth.signInWithPassword({{email:$('admEmail').value,password:$('admPass').value}});if(r.error)return st(r.error.message);$('loginPanel').style.display='none';$('appPanel').style.display='block';st('Login realizado');load()}};$('logout').onclick=async()=>{{await sb.auth.signOut();location.reload()}};$('newEvent').onclick=clear;$('cancelEdit').onclick=clear;$('admClose').onclick=()=>location.href='index.html';$('saveEvent').onclick=async()=>{{const name=$('fName').value,payload={{name,event_date:$('fDate').value,location:$('fLocation').value,artists:$('fArtists').value,purchase_url:$('fPurchase').value,image_url:$('fImage').value,source_url:$('fSource').value,description:$('fDescription').value,published:$('fPublished').value==='true',featured:$('fFeatured').value==='true',slug:name.toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'')}};const r=editId?await sb.from('events').update(payload).eq('id',editId):await sb.from('events').insert(payload);st(r.error?.message||'Evento salvo');if(!r.error){{clear();load()}}}}}};load()}};const sc=document.createElement('script');sc.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2';sc.onload=load;document.head.appendChild(sc)}}
function indexPage(){{document.body.classList.add('v3-page-pad');document.body.id='top';const search=document.querySelector('.search input');if(search){{search.placeholder='Buscar por evento, artista, local ou mês...';search.addEventListener('input',()=>{{const q=search.value.toLowerCase().trim();document.querySelectorAll('.cards .card').forEach(c=>c.style.display=(!q||c.textContent.toLowerCase().includes(q))?'':'none')}})}}const fs=getFav();document.querySelectorAll('.cards .card').forEach(c=>{{const a=c.querySelector('a[href*="event.html?event="]');if(!a)return;const slug=new URL(a.href,location.href).searchParams.get('event');c.dataset.slug=slug;const b=document.createElement('button');b.className='v3-fav'+(fs.includes(slug)?' on':'');b.textContent=fs.includes(slug)?'♥':'♡';b.onclick=e=>{{e.preventDefault();e.stopPropagation();let x=getFav();if(x.includes(slug)){{x=x.filter(v=>v!==slug);b.classList.remove('on');b.textContent='♡';toast('Removido dos favoritos')}}else{{x.push(slug);b.classList.add('on');b.textContent='♥';toast('Adicionado aos favoritos')}}setFav(x)}};c.querySelector('.pic')?.appendChild(b);c.addEventListener('mousemove',e=>{{const r=c.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;c.style.transform=`perspective(900px) rotateX(${{-y*5}}deg) rotateY(${{x*6}}deg) translateY(-4px)`}});c.addEventListener('mouseleave',()=>c.style.transform='')}});if(params.get('favorites')==='1')document.querySelectorAll('.cards .card').forEach(c=>c.style.display=fs.includes(c.dataset.slug)?'':'none');document.querySelectorAll('[data-v3-search]').forEach(b=>b.onclick=()=>{{search?.scrollIntoView({{behavior:'smooth',block:'center'}});setTimeout(()=>search?.focus(),350)}})}}
function eventPage(){{document.body.classList.add('v3-page-pad');const slug=params.get('event'),fs=getFav(),act=document.querySelector('.actions');if(act){{const s=document.createElement('button');s.className='btn v3-share';s.type='button';s.textContent='↗ Compartilhar';s.onclick=()=>share(location.href,document.getElementById('name')?.textContent||'Evento BeOn');act.appendChild(s);const f=document.createElement('button');f.className='btn v3-share';f.type='button';f.textContent=fs.includes(slug)?'♥ Favoritado':'♡ Favoritar';f.onclick=()=>{{let x=getFav();if(x.includes(slug)){{x=x.filter(v=>v!==slug);f.textContent='♡ Favoritar';toast('Removido dos favoritos')}}else{{x.push(slug);f.textContent='♥ Favoritado';toast('Adicionado aos favoritos')}}setFav(x)}};act.appendChild(f)}}const count=document.querySelector('.count');count?.classList.add('v3-count');const last=['','','',''];const obs=new MutationObserver(()=>document.querySelectorAll('.count .unit b').forEach((el,i)=>{{const v=el.textContent;if(v!==last[i]){{if(last[i]){{el.closest('.unit').classList.remove('flip');void el.offsetWidth;el.closest('.unit').classList.add('flip')}}last[i]=v}}}}));count&&obs.observe(count,{{subtree:true,childList:true,characterData:true}});const loc=document.getElementById('local')?.textContent||'';if(loc){{const m=document.createElement('section');m.className='v3-map';m.innerHTML=`<div class="v3-map-head"><span>📍 Localização</span><a class="v3-share" style="padding:8px 10px;border-radius:8px;font-size:10px" target="_blank" href="https://www.google.com/maps/search/?api=1&query=${{encodeURIComponent(loc)}}">Abrir no Maps ↗</a></div><iframe loading="lazy" src="https://www.google.com/maps?q=${{encodeURIComponent(loc)}}&output=embed"></iframe>`;document.querySelector('.hero')?.after(m)}}document.querySelectorAll('[data-v3-search]').forEach(b=>b.onclick=()=>location.href='index.html?focus=search#eventos')}}
function boot(){{document.head.insertAdjacentHTML('beforeend',STYLE);document.body.insertAdjacentHTML('beforeend',NAV);if(params.get('admin')==='1')admin();else if(location.pathname.endsWith('event.html'))eventPage();else indexPage()}}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();}})();</script>'''
for name in ('index.html','event.html'):
    p=Path(name);s=p.read_text(encoding='utf-8')
    if 'beon-v3-script' not in s:
        s=s.replace('</body>',SCRIPT+'</body>',1)
        p.write_text(s,encoding='utf-8')
